<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { Instance } from '../../shared/model'
import type { ModFile } from '../../shared/resources'
import { busy,run,toast } from '../store'
import Icon from './Icon.vue'
const props=defineProps<{instance:Instance;embedded?:boolean}>(),emit=defineEmits<{close:[];download:[]}>()
const files=ref<ModFile[]>([]),query=ref(''),loading=ref(false)
const filtered=computed(()=>files.value.filter(f=>(f.name+' '+f.file).toLowerCase().includes(query.value.toLowerCase())))
const locked=computed(()=>props.instance.running||props.instance.protected)
async function action(method:string,file?:string){loading.value=true;try{const result=await run('mods-'+props.instance.id,method,file?{id:props.instance.id,file}:props.instance.id);if(result)files.value=result}finally{loading.value=false}}
onMounted(()=>action('mods.list'))
</script>
<template><div :class="embedded?'mods-embedded':'modal-backdrop'" @click.self="embedded?undefined:emit('close')"><section class="modal mods-modal" :class="{embedded}"><header><h2>{{instance.name}} · Mod 管理</h2><button class="bare" aria-label="关闭 Mod 管理" @click="emit('close')"><Icon name="x"/></button></header><div class="modal-body"><p class="field-hint">{{instance.gameDir}} / mods</p><p v-if="!instance.isolated" class="inline-notice">此实例使用共享游戏目录，这里的修改也会影响使用相同目录的其他实例。</p><p v-if="locked" class="inline-notice">实例已保护或正在运行，目前只能查看。</p><div class="mod-toolbar"><input v-model="query" class="full-input" aria-label="搜索模组" placeholder="搜索模组名称或文件…"/><button class="button compact" :disabled="loading" @click="action('mods.list')">刷新</button><button class="button compact" :disabled="locked||loading" @click="action('mods.import')">导入</button><button class="button primary compact" @click="emit('download')">下载 Mod</button></div><p v-if="!files.length" class="field-hint">{{loading?'正在读取模组…':'尚无模组，可导入本地 JAR 或下载兼容模组。'}}</p><div v-for="file in filtered" :key="file.file" class="mod-row"><img v-if="file.icon" class="mod-icon" :src="file.icon" alt=""/><span v-else class="mod-icon fallback">{{file.name.slice(0,1)}}</span><div><b>{{file.name}}</b><small>{{file.version||'未提供版本'}} · {{(file.size/1048576).toFixed(2)}} MiB · {{file.enabled?'已启用':'已禁用'}}</small><p>{{file.file}}</p><p v-if="file.issue" class="danger-text">{{file.issue}}</p></div><button class="button compact" :disabled="locked||loading" @click="action('mods.toggle',file.file)">{{file.enabled?'禁用':'启用'}}</button><button class="bare danger-text" title="将模组移至回收站" :disabled="locked||loading" @click="action('mods.delete',file.file)"><Icon name="trash" :size="16"/></button></div></div><footer><span class="field-hint">{{files.length}} 个模组</span><button class="button" @click="emit('close')">关闭</button></footer></section></div></template>
